INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6958393, 1049366, 83313, '<td valign="top">There are a ton of compression artifacts visible in this image, and the 45k file size also says you used a ton of compression. Compression kills detail. always used as large a file size as you can get away with and still fit the challenge requirements. <br/> <br/>Aside from that, the composition is good, you shot in good light, and with some appropriate tweaks, this scene has a lot of good potential. So, poor vote on the post processing, good for the capture itself. Evens out to a 5 for me.</td>', 'There are a ton of compression artifacts visible in this image, and the 45k file size also says you used a ton of compression. Compression kills detail. always used as large a file size as you can get away with and still fit the challenge requirements.  Aside from that, the composition is good, you shot in good light, and with some appropriate tweaks, this scene has a lot of good potential. So, poor vote on the post processing, good for the capture itself. Evens out to a 5 for me.', '2013-01-16 00:17:40.000000', NULL, 1),
(6958396, 1049281, 83313, '<td valign="top">Nice action shot with a dramatic look to it.</td>', 'Nice action shot with a dramatic look to it.', '2013-01-16 00:19:09.000000', NULL, 1),
(6958405, 1048635, 16046, '<td valign="top">Best in show award, congrats, you nailed it!</td>', 'Best in show award, congrats, you nailed it!', '2013-01-16 00:36:07.000000', NULL, 1),
(6958406, 1049470, 16046, '<td valign="top">top 3</td>', 'top 3', '2013-01-16 00:36:26.000000', NULL, 1),
(6958409, 1049423, 16046, '<td valign="top">Top 3</td>', 'Top 3', '2013-01-16 00:36:59.000000', NULL, 1),
(6958424, 1049074, 157652, '<td valign="top">Great picture, and great fit for this challenge. The boat''s color offsets it from the rest of the image, drawing immediate attention to it. The sky sets a menacing mood. The shore occupies just enough of the image to make it well balanced.</td>', 'Great picture, and great fit for this challenge. The boat''s color offsets it from the rest of the image, drawing immediate attention to it. The sky sets a menacing mood. The shore occupies just enough of the image to make it well balanced.', '2013-01-16 00:59:21.000000', NULL, 1),
(6958427, 1049656, 157652, '<td valign="top">Good composition. Nice subtle lavender on an otherwise grayscale image. The background (2nd row of chairs etc.) is a bit distracting though.</td>', 'Good composition. Nice subtle lavender on an otherwise grayscale image. The background (2nd row of chairs etc.) is a bit distracting though.', '2013-01-16 01:02:29.000000', NULL, 1),
(6958429, 1049360, 157652, '<td valign="top">Intriguing picture with good colors. Did you use tape or string to position the petals?</td>', 'Intriguing picture with good colors. Did you use tape or string to position the petals?', '2013-01-16 01:06:57.000000', NULL, 1),
(6958430, 1049020, 157652, '<td valign="top">The composition is too simple to be interesting, IMO. Cut the lemon, perhaps? ;)</td>', 'The composition is too simple to be interesting, IMO. Cut the lemon, perhaps? ;)', '2013-01-16 01:08:25.000000', NULL, 1),
(6958431, 1049534, 157652, '<td valign="top">Too simple to be interesting, IMO.</td>', 'Too simple to be interesting, IMO.', '2013-01-16 01:10:29.000000', NULL, 1),
(6958432, 1049003, 157652, '<td valign="top">Great color on the flower. The background is quite distracting though. A lower angle might have been more interesting.</td>', 'Great color on the flower. The background is quite distracting though. A lower angle might have been more interesting.', '2013-01-16 01:11:24.000000', NULL, 1),
(6958433, 1049109, 157652, '<td valign="top">I wish that I could zoom out and see what else was going on in the scene :)</td>', 'I wish that I could zoom out and see what else was going on in the scene :)', '2013-01-16 01:12:09.000000', NULL, 1),
(6958436, 1048673, 157652, '<td valign="top">Looks like it could be a generated image rather than a photograph ;)</td>', 'Looks like it could be a generated image rather than a photograph ;)', '2013-01-16 01:13:05.000000', NULL, 1),
(6958440, 1049419, 157652, '<td valign="top">Great lighting on the background -- it draws attention to the subject.</td>', 'Great lighting on the background -- it draws attention to the subject.', '2013-01-16 01:14:33.000000', NULL, 1),
(6958441, 1049429, 157652, '<td valign="top">Wondering if this was a single exposure, or a composite of two images.</td>', 'Wondering if this was a single exposure, or a composite of two images.', '2013-01-16 01:16:03.000000', NULL, 1),
(6958443, 1049629, 157652, '<td valign="top">Nice color on the flowers, but background is kind of distracting. Might have been more interesting to focus on one of the flowers, the one that isn''t withering?</td>', 'Nice color on the flowers, but background is kind of distracting. Might have been more interesting to focus on one of the flowers, the one that isn''t withering?', '2013-01-16 01:18:17.000000', NULL, 1),
(6958446, 1049421, 157652, '<td valign="top">Background is too distracting; would''ve been better blurred more IMO. The picture doesn''t explain how the flower relates to the scene :)</td>', 'Background is too distracting; would''ve been better blurred more IMO. The picture doesn''t explain how the flower relates to the scene :)', '2013-01-16 01:19:37.000000', NULL, 1),
(6958448, 1048857, 157652, '<td valign="top">Great color on the subject; draws attention immediately. There would be more room to breathe, IMO, without the tree trunk (?) in the top-left corner.</td>', 'Great color on the subject; draws attention immediately. There would be more room to breathe, IMO, without the tree trunk (?) in the top-left corner.', '2013-01-16 01:22:09.000000', NULL, 1),
(6958450, 1049047, 157652, '<td valign="top">More separation between subject and background would''ve helped, IMO. Colors are too similar as it stands. Still a good portrait though.</td>', 'More separation between subject and background would''ve helped, IMO. Colors are too similar as it stands. Still a good portrait though.', '2013-01-16 01:24:16.000000', NULL, 1),
(6958451, 1049363, 157652, '<td valign="top">Nice detail and nice shallow depth of field! A darker background would''ve helped, IMO.</td>', 'Nice detail and nice shallow depth of field! A darker background would''ve helped, IMO.', '2013-01-16 01:24:58.000000', NULL, 1),
(6958452, 1049149, 157652, '<td valign="top">I like the fog, but I wish there was something there (apart from the subject) to help me tell how large the space is.</td>', 'I like the fog, but I wish there was something there (apart from the subject) to help me tell how large the space is.', '2013-01-16 01:25:52.000000', NULL, 1),
(6958454, 1048920, 157652, '<td valign="top">Even desaturated, the background is too busy IMO. Would''ve benefited from more blurring :)</td>', 'Even desaturated, the background is too busy IMO. Would''ve benefited from more blurring :)', '2013-01-16 01:27:57.000000', NULL, 1),
(6958455, 1049590, 157652, '<td valign="top">Nice detail on the flower! I found myself wishing for a tighter crop :)</td>', 'Nice detail on the flower! I found myself wishing for a tighter crop :)', '2013-01-16 01:28:36.000000', NULL, 1),
(6958457, 1049420, 157652, '<td valign="top">Great detail, striking colors, nice blurred background. I only wish the top of the bird''s tail wasn''t cut off ;)</td>', 'Great detail, striking colors, nice blurred background. I only wish the top of the bird''s tail wasn''t cut off ;)', '2013-01-16 01:29:52.000000', NULL, 1),
(6958458, 1049511, 157652, '<td valign="top">Great detail in the sky. Nice deep blacks.</td>', 'Great detail in the sky. Nice deep blacks.', '2013-01-16 01:32:15.000000', NULL, 1),
(6958459, 1049232, 157652, '<td valign="top">Nice eye color, but I wish the rest of the face wasn''t that far overexposed ;)</td>', 'Nice eye color, but I wish the rest of the face wasn''t that far overexposed ;)', '2013-01-16 01:33:10.000000', NULL, 1),
(6958460, 1049385, 157652, '<td valign="top">I wish there was more sharpness / clarity in the center.</td>', 'I wish there was more sharpness / clarity in the center.', '2013-01-16 01:33:52.000000', NULL, 1),
(6958461, 1049655, 157652, '<td valign="top">White objects disappear on the white background; perhaps a darker background would''ve been better.</td>', 'White objects disappear on the white background; perhaps a darker background would''ve been better.', '2013-01-16 01:34:20.000000', NULL, 1),
(6958462, 1048698, 157652, '<td valign="top">Nice colors and cool shadows :)</td>', 'Nice colors and cool shadows :)', '2013-01-16 01:34:56.000000', NULL, 1),
(6958464, 1049628, 157652, '<td valign="top">Very cool creature :) I just wish there was more separation between the subject''s colors and the background colors.</td>', 'Very cool creature :) I just wish there was more separation between the subject''s colors and the background colors.', '2013-01-16 01:35:59.000000', NULL, 1),
(6958468, 1049545, 157652, '<td valign="top">I like this; it makes me think of abandoned buildings and suspenseful video games ;)</td>', 'I like this; it makes me think of abandoned buildings and suspenseful video games ;)', '2013-01-16 01:37:46.000000', NULL, 1),
(6958470, 1049344, 157652, '<td valign="top">Nice picture, but not a great fit for this challenge.</td>', 'Nice picture, but not a great fit for this challenge.', '2013-01-16 01:38:25.000000', NULL, 1),
(6958471, 1049713, 157652, '<td valign="top">I like the perspective :)</td>', 'I like the perspective :)', '2013-01-16 01:38:51.000000', NULL, 1),
(6958472, 1049182, 157652, '<td valign="top">This must''ve been interesting to watch :) I like the colors and the composition; I only wish the background wasn''t so busy.</td>', 'This must''ve been interesting to watch :) I like the colors and the composition; I only wish the background wasn''t so busy.', '2013-01-16 01:39:59.000000', NULL, 1),
(6958473, 1049630, 157652, '<td valign="top">Build a bigger campfire so you can get more light ;)</td>', 'Build a bigger campfire so you can get more light ;)', '2013-01-16 01:40:24.000000', NULL, 1),
(6958477, 1049320, 157652, '<td valign="top">Thumbs up for an interesting perspective on everyday objects!</td>', 'Thumbs up for an interesting perspective on everyday objects!', '2013-01-16 01:42:13.000000', NULL, 1),
(6958478, 1049541, 157652, '<td valign="top">Subject and background colors collide, IMO. Darker background would''ve been better.</td>', 'Subject and background colors collide, IMO. Darker background would''ve been better.', '2013-01-16 01:42:57.000000', NULL, 1),
(6958482, 1049334, 157652, '<td valign="top">I like the smoky details in the bottle''s shadow!</td>', 'I like the smoky details in the bottle''s shadow!', '2013-01-16 01:43:48.000000', NULL, 1),
(6958483, 1049139, 157652, '<td valign="top">Good colors. Perfect background.</td>', 'Good colors. Perfect background.', '2013-01-16 01:44:22.000000', NULL, 1),
