(6958487, 1049182, 152252, '<td valign="top">Great processing, light, colors and subject.</td>', 'Great processing, light, colors and subject.', '2013-01-16 01:45:35.000000', NULL, 1),
(6958489, 1049372, 152252, '<td valign="top">Amazing picture. Beautiful colors, and the atmosphere, which made a simple leaf look fantastic!</td>', 'Amazing picture. Beautiful colors, and the atmosphere, which made a simple leaf look fantastic!', '2013-01-16 01:46:54.000000', NULL, 1),
