(6958492, 1049654, 152252, '<td valign="top">:) That''s super funny. Great processing and idea. Good job!!</td>', ':) That''s super funny. Great processing and idea. Good job!!', '2013-01-16 01:48:08.000000', NULL, 1),
(6958494, 1049150, 157652, '<td valign="top">Nice composition :) I like how the sign in the background is just out-of-focus enough to still be readable.</td>', 'Nice composition :) I like how the sign in the background is just out-of-focus enough to still be readable.', '2013-01-16 01:48:54.000000', NULL, 1),
