(6958523, 1049392, 157652, '<td valign="top">Are the circles some kind of lens / marble, or did you do this in post?</td>', 'Are the circles some kind of lens / marble, or did you do this in post?', '2013-01-16 02:02:10.000000', NULL, 1),
(6958524, 1049549, 157652, '<td valign="top">I like how the green extends to three of the four corners.</td>', 'I like how the green extends to three of the four corners.', '2013-01-16 02:02:39.000000', NULL, 1),
(6958527, 1049233, 157652, '<td valign="top">Cool reflections in the water! Maybe with a lower point of view and a tighter crop, you could hide some of those distracting trees.</td>', 'Cool reflections in the water! Maybe with a lower point of view and a tighter crop, you could hide some of those distracting trees.', '2013-01-16 02:03:44.000000', NULL, 1),
