(6958538, 1049597, 157652, '<td valign="top">Cool :) Might have been even better with a tighter crop, and perhaps a POV that is lower and from one side.</td>', 'Cool :) Might have been even better with a tighter crop, and perhaps a POV that is lower and from one side.', '2013-01-16 02:15:56.000000', NULL, 1),
(6958539, 1048956, 157652, '<td valign="top">Nice shallow depth of field :) Cool perspective and composition.</td>', 'Nice shallow depth of field :) Cool perspective and composition.', '2013-01-16 02:17:32.000000', NULL, 1),
