(6958842, 1048635, 153814, '<td valign="top">WOW what a cool shot and alot of fun to look at.<br/>One of my top picks.</td>', 'WOW what a cool shot and alot of fun to look at.One of my top picks.', '2013-01-16 09:44:31.000000', NULL, 1),
(6958846, 1049593, 153814, '<td valign="top">Interesting and creative take on the challenge.<br/>Simple yet different very well done.<br/>Great reflection. Fits the challenge well.</td>', 'Interesting and creative take on the challenge.Simple yet different very well done.Great reflection. Fits the challenge well.', '2013-01-16 09:46:20.000000', NULL, 1),
(6958851, 1049549, 153814, '<td valign="top">Creative shot, it works for me.<br/>I really like the red shadow thats being cast.</td>', 'Creative shot, it works for me.I really like the red shadow thats being cast.', '2013-01-16 09:48:45.000000', NULL, 1),
(6958855, 1049045, 153814, '<td valign="top">Mesmerizing shot I could look at this for hours.<br/>Well done.</td>', 'Mesmerizing shot I could look at this for hours.Well done.', '2013-01-16 09:49:50.000000', NULL, 1),
(6958856, 1049360, 153814, '<td valign="top">What a great idea this is one of my top picks.<br/>Very creative.</td>', 'What a great idea this is one of my top picks.Very creative.', '2013-01-16 09:50:53.000000', NULL, 1),
(6958857, 1049431, 112539, '<td valign="top">Had to give this a lower score because I am not sure which is the burst of color. Too many. Challenge was to use color to off set your subject. Not sure which subject you are trying to offset. The foreground is what initially pops for me but then so much other color.</td>', 'Had to give this a lower score because I am not sure which is the burst of color. Too many. Challenge was to use color to off set your subject. Not sure which subject you are trying to offset. The foreground is what initially pops for me but then so much other color.', '2013-01-16 09:51:19.000000', NULL, 1),
(6958859, 1049109, 153814, '<td valign="top">Great shot not matter where I look my eyes are drawn to that big pink tounge. Well done.</td>', 'Great shot not matter where I look my eyes are drawn to that big pink tounge. Well done.', '2013-01-16 09:52:43.000000', NULL, 1),
(6958861, 1049691, 112539, '<td valign="top">Color is supposed to offset your subject from the rest of the photo. There isn''t one burst of color that offsets. The color is all around.</td>', 'Color is supposed to offset your subject from the rest of the photo. There isn''t one burst of color that offsets. The color is all around.', '2013-01-16 09:55:02.000000', NULL, 1),
(6958866, 1048883, 112539, '<td valign="top">Too much other color in the photo to know what is being offset. I am thinking it is the water but it doesn''t burst with color more than any other color in the photo which is what the challenge was.</td>', 'Too much other color in the photo to know what is being offset. I am thinking it is the water but it doesn''t burst with color more than any other color in the photo which is what the challenge was.', '2013-01-16 09:57:02.000000', NULL, 1),
(6958867, 1049296, 153814, '<td valign="top">Not easy getting a shot of these skittish little buggers especially when in display mode. Nice crisp image as well. The only knock I have is that white spot in front of him is a bit distracting. Still one of my top picks I though it met the challenge to a "T".</td>', 'Not easy getting a shot of these skittish little buggers especially when in display mode. Nice crisp image as well. The only knock I have is that white spot in front of him is a bit distracting. Still one of my top picks I though it met the challenge to a "T".', '2013-01-16 09:57:58.000000', NULL, 1),
(6958869, 1048956, 153814, '<td valign="top">Is that a Red Eft? Cool shot. Those little buggers look like candy I just want to eat them. Good job on this.</td>', 'Is that a Red Eft? Cool shot. Those little buggers look like candy I just want to eat them. Good job on this.', '2013-01-16 09:59:27.000000', NULL, 1),
(6958872, 1049644, 153814, '<td valign="top">Very nice shot, well done.</td>', 'Very nice shot, well done.', '2013-01-16 10:02:15.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6958873, 1049419, 112539, '<td valign="top">I really like this photo but don''t really see a "burst of color" just a little bit of a red tie. The offset in this photo is more the monochrome suit and shirt against the gold background not the red tie. That is just a small addition to the photo...not the color offset which was the challenge.</td>', 'I really like this photo but don''t really see a "burst of color" just a little bit of a red tie. The offset in this photo is more the monochrome suit and shirt against the gold background not the red tie. That is just a small addition to the photo...not the color offset which was the challenge.', '2013-01-16 10:02:53.000000', NULL, 1),
(6958874, 1049646, 153814, '<td valign="top">What I great idea for this challenge.<br/>Well done.</td>', 'What I great idea for this challenge.Well done.', '2013-01-16 10:03:16.000000', NULL, 1),
(6958875, 1049421, 112539, '<td valign="top">Had to rate this lower due to the distracting background. Better if you had held a black piece of paper behind the flower. Light on flower nice but my eye wanders from that tot he blue and purple tops in the background.</td>', 'Had to rate this lower due to the distracting background. Better if you had held a black piece of paper behind the flower. Light on flower nice but my eye wanders from that tot he blue and purple tops in the background.', '2013-01-16 10:06:24.000000', NULL, 1),
(6958876, 1049151, 153814, '<td valign="top">The idea is right on the money but it could have been executed better.<br/>I can''t really find the point that the camera focused on.</td>', 'The idea is right on the money but it could have been executed better.I can''t really find the point that the camera focused on.', '2013-01-16 10:06:50.000000', NULL, 1),
(6958878, 1049628, 112539, '<td valign="top">So much purple in the background that I don''t see that the burst of color is really offsetting which was the challenge.</td>', 'So much purple in the background that I don''t see that the burst of color is really offsetting which was the challenge.', '2013-01-16 10:09:48.000000', NULL, 1),
(6958882, 1049403, 112539, '<td valign="top">I don''t consider white a burst of color. White is the absence of color.</td>', 'I don''t consider white a burst of color. White is the absence of color.', '2013-01-16 10:11:56.000000', NULL, 1),
(6958883, 1049344, 112539, '<td valign="top">I see no burst of color here.</td>', 'I see no burst of color here.', '2013-01-16 10:13:06.000000', NULL, 1),
(6958887, 1048920, 112539, '<td valign="top">Would have liked to see a brighter color on these flowers as the challenge was burst of color.</td>', 'Would have liked to see a brighter color on these flowers as the challenge was burst of color.', '2013-01-16 10:14:42.000000', NULL, 1),
(6958893, 1049281, 58457, '<td valign="top">Fits the challenge, good freeze... I wish I could see a little more detail in the snow to see the terrain that he is skiing on.</td>', 'Fits the challenge, good freeze... I wish I could see a little more detail in the snow to see the terrain that he is skiing on.', '2013-01-16 10:18:52.000000', NULL, 1),
(6958901, 1049496, 112539, '<td valign="top">Not sure what the burst of color is that is the offset. The only color that jumps out is the picture over the man''s head but the column in the foreground is so distracting that it really annoys rather than enhances the photo. If the column was supposed to be the offset, it has no real "burst" of color.</td>', 'Not sure what the burst of color is that is the offset. The only color that jumps out is the picture over the man''s head but the column in the foreground is so distracting that it really annoys rather than enhances the photo. If the column was supposed to be the offset, it has no real "burst" of color.', '2013-01-16 10:29:47.000000', NULL, 1),
(6958904, 1049402, 112539, '<td valign="top">Color is supposed to offset your subject from the rest of the photo. There isn''t one burst of color that offsets. The color is all around.</td>', 'Color is supposed to offset your subject from the rest of the photo. There isn''t one burst of color that offsets. The color is all around.', '2013-01-16 10:31:51.000000', NULL, 1),
(6958915, 1049295, 54446, '<td valign="top">My favorite in this challenge.  Good job of incorporating that red coat into this well known waterfall and bridge scene.  I had a similar idea, as a goal, but the weather kept the people home on the day I shot.  10</td>', 'My favorite in this challenge.  Good job of incorporating that red coat into this well known waterfall and bridge scene.  I had a similar idea, as a goal, but the weather kept the people home on the day I shot.  10', '2013-01-16 10:45:11.000000', NULL, 1),
(6958936, 1049654, 118154, '<td valign="top">I like this  in many different ways.</td>', 'I like this  in many different ways.', '2013-01-16 11:01:11.000000', NULL, 1),
(6958939, 1049419, 118154, '<td valign="top">Wish this was just the background light.</td>', 'Wish this was just the background light.', '2013-01-16 11:02:40.000000', NULL, 1),
(6958947, 1049360, 118154, '<td valign="top">This is neat,good work.</td>', 'This is neat,good work.', '2013-01-16 11:09:56.000000', NULL, 1),
(6958949, 1049644, 118154, '<td valign="top">Nice shot and model.</td>', 'Nice shot and model.', '2013-01-16 11:10:21.000000', NULL, 1),
(6958951, 1049700, 118154, '<td valign="top">Love this,real good to look at and different.</td>', 'Love this,real good to look at and different.', '2013-01-16 11:11:01.000000', NULL, 1),
(6958952, 1049444, 118154, '<td valign="top">Fab capture.</td>', 'Fab capture.', '2013-01-16 11:11:31.000000', NULL, 1),
