(6959083, 1049151, 77196, '<td valign="top">Nice concept, nice color.</td>', 'Nice concept, nice color.', '2013-01-16 12:44:25.000000', NULL, 1),
(6959085, 1049344, 77196, '<td valign="top">Nice picture of London, but nothing stands out to me as a burst of color. Big Ben looks to be tilting slightly to the right. I like the subtle differences in shades of brown, and the contrasting textures of the water, sky, and buildings.</td>', 'Nice picture of London, but nothing stands out to me as a burst of color. Big Ben looks to be tilting slightly to the right. I like the subtle differences in shades of brown, and the contrasting textures of the water, sky, and buildings.', '2013-01-16 12:46:50.000000', NULL, 1),
(6959086, 1049421, 77196, '<td valign="top">Nice flower shot - maybe a bit too much flash. Busy, busy background (maybe it is just me, but those young ladies in the background are a definite distraction).</td>', 'Nice flower shot - maybe a bit too much flash. Busy, busy background (maybe it is just me, but those young ladies in the background are a definite distraction).', '2013-01-16 12:47:57.000000', NULL, 1),
