(6959793, 1049624, 101256, '<td valign="top">I actually cleaned my glasses (TWICE!!)- I couldn''t make heads or tales out of this image with respect to the challenge - still can''t. Don''t take offense - it probably makes sense to others, I don''t mind subtle but ambiguity and I don''t get along. Accordingly, and as is my wont in cases like this, marks go to the author.</td>', 'I actually cleaned my glasses (TWICE!!)- I couldn''t make heads or tales out of this image with respect to the challenge - still can''t. Don''t take offense - it probably makes sense to others, I don''t mind subtle but ambiguity and I don''t get along. Accordingly, and as is my wont in cases like this, marks go to the author.', '2013-01-17 15:32:31.000000', NULL, 1),
(6959794, 1049366, 101256, '<td valign="top">Very interesting image - the colors are a little weaker than I would like to see, but still, very pleasing to the eye.  A worthy entry into the challenge.</td>', 'Very interesting image - the colors are a little weaker than I would like to see, but still, very pleasing to the eye.  A worthy entry into the challenge.', '2013-01-17 15:33:39.000000', NULL, 1),
(6959795, 1049423, 101256, '<td valign="top">Simply lovely - the bright blue against the earth tone is a perfect match.  A terrific composition - well done. Should be a top ten.</td>', 'Simply lovely - the bright blue against the earth tone is a perfect match.  A terrific composition - well done. Should be a top ten.', '2013-01-17 15:34:39.000000', NULL, 1),
(6959797, 1049334, 101256, '<td valign="top">Another great contrast of color and perfectly matches the spirit of the challenge. The color is not over done and the background is perfectly in harmony with the bottle. Very very nice image - well done.</td>', 'Another great contrast of color and perfectly matches the spirit of the challenge. The color is not over done and the background is perfectly in harmony with the bottle. Very very nice image - well done.', '2013-01-17 15:36:29.000000', NULL, 1),
(6959798, 1049371, 101256, '<td valign="top">Another great image - perfect complimentary colors and highly detailed and pleasing shapes.  Wonderful entry into the challenge.</td>', 'Another great image - perfect complimentary colors and highly detailed and pleasing shapes.  Wonderful entry into the challenge.', '2013-01-17 15:37:44.000000', NULL, 1),
(6959799, 1049074, 101256, '<td valign="top">Ok this is getting ridiculous - another perfect image with beautifully contrasting colors and shapes. Three in a row of beautiful and excellently composed images. Well done.</td>', 'Ok this is getting ridiculous - another perfect image with beautifully contrasting colors and shapes. Three in a row of beautiful and excellently composed images. Well done.', '2013-01-17 15:38:54.000000', NULL, 1),
(6959800, 1049541, 101256, '<td valign="top">The orange doesn''t really work against the tan background and green carpet. It certainly is a "burst" of color, but not a pleasing one to me anyway.</td>', 'The orange doesn''t really work against the tan background and green carpet. It certainly is a "burst" of color, but not a pleasing one to me anyway.', '2013-01-17 15:39:58.000000', NULL, 1),
(6959802, 1049714, 101256, '<td valign="top">Sadly, the blue edging around the nose and head (an indication of over sharpening and saturation) seriously detracts from this image.</td>', 'Sadly, the blue edging around the nose and head (an indication of over sharpening and saturation) seriously detracts from this image.', '2013-01-17 15:41:26.000000', NULL, 1),
(6959804, 1049419, 101256, '<td valign="top">Somebody saw "Gangster Squad" huh?  Very nice image - subtle tones, differently muted colors - a worthy entry into the challenge.</td>', 'Somebody saw "Gangster Squad" huh?  Very nice image - subtle tones, differently muted colors - a worthy entry into the challenge.', '2013-01-17 15:42:52.000000', NULL, 1),
(6959810, 1049700, 108580, '<td valign="top">Beautiful. Superbly lit and photographed. Kudos also to stylist and MUA.</td>', 'Beautiful. Superbly lit and photographed. Kudos also to stylist and MUA.', '2013-01-17 15:51:34.000000', NULL, 1),
