(6961352, 1049180, 118154, '<td valign="top">Nice colors here,I like it.</td>', 'Nice colors here,I like it.', '2013-01-20 10:41:34.000000', NULL, 1),
(6961508, 1049180, 136989, '<td valign="top">Absolutely adorable. The turquoise really accents the eye color/detail.</td>', 'Absolutely adorable. The turquoise really accents the eye color/detail.', '2013-01-20 17:57:01.000000', NULL, 1),
(6961744, 1049549, 157179, '<td valign="top">Beautiful lines using each of 3 corners almost perfectly. The burst is both, the green and then the red. Picture composition is perfect.Excellent use of reflective device. Superb lighting, strong but not too hot. Focus point in DOF chosen correctly,<br/>right where the key light hits the subject in the green, not directly on the red. Remember the red is almost secondary. I see the cake, but there''s more, I see the icing. For me this is a great picture.</td>', 'Beautiful lines using each of 3 corners almost perfectly. The burst is both, the green and then the red. Picture composition is perfect.Excellent use of reflective device. Superb lighting, strong but not too hot. Focus point in DOF chosen correctly,right where the key light hits the subject in the green, not directly on the red. Remember the red is almost secondary. I see the cake, but there''s more, I see the icing. For me this is a great picture.', '2013-01-21 03:27:20.000000', NULL, 1),
(6961745, 1049015, 157179, '<td valign="top">Don''t really see a burst, here</td>', 'Don''t really see a burst, here', '2013-01-21 03:31:17.000000', NULL, 1),
